    def test_slice_bounds_and_queryset_reuse(self):
        for relation in ("authors", "first_time_authors"):
            for bounds in (slice(0, 2), slice(1, 2), slice(1, None), slice(0, 0)):
                with self.subTest(relation=relation, bounds=bounds):
                    authors = Author.objects.exclude(name="Anne").order_by("-name")
                    sliced_authors = authors[bounds]
                    expected = {
                        book.pk: list(getattr(book, relation).filter(
                            name__in=authors.values("name")
                        ).order_by("-name"))[bounds]
                        for book in Book.objects.all()
                    }
                    for _ in range(2):
                        with self.assertNumQueries(1 if bounds.stop == 0 else 2):
                            books = list(Book.objects.prefetch_related(
                                Prefetch(relation, sliced_authors, to_attr="examples")
                            ))
                        for book in books:
                            self.assertEqual(book.examples, expected[book.pk])
                    self.assertEqual(sliced_authors.query.low_mark, bounds.start)
                    self.assertEqual(sliced_authors.query.high_mark, bounds.stop)

